WITH recent_web_events AS (SELECT *, DATE_TRUNC('YEAR', event_time) AS event_time_period FROM web_events WHERE session_id IN (11, 34)), agg AS (SELECT event_type, session_id, SUM(CASE WHEN page = '/checkout' THEN 1 ELSE 0 END) AS checkout_count FROM recent_web_events GROUP BY event_type, session_id) SELECT event_type, session_id, checkout_count FROM agg WHERE checkout_count >= 29;
